"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[52374],{9450:e=>{e.exports=JSON.parse('{"id":"2026-07-17-moobidesk-renamed-to-converse","date":"2026-07-17","products":["Converse"],"product":"Converse","channel":"","changeType":"Changed","title":"Moobidesk renamed to Converse","excerpt":"The product previously known as Moobidesk is now called Converse throughout the developer documentation. All functionality is identical \u2014 only the product name has changed, so there is no API or behavioural change to act on.","hasArticle":true,"bodyHtml":"<p>The product previously known as <strong>Moobidesk</strong> is now called <strong>Converse</strong> throughout the developer documentation. All functionality is identical \u2014 only the product name has changed, so there is no API or behavioural change to act on.</p>\\n<p>Converse is a unified conversational platform for omnichannel customer engagement across WhatsApp, Email, and Facebook Messenger, with conversation management, queue routing, broadcast messaging, and real-time analytics.</p>\\n<p>The login URL is unchanged \u2014 you still access Converse through your organization&#39;s <code>moobidesk.com</code> URL with your existing credentials.</p>\\n<ul>\\n<li><a href=\\"/connect/docs/converse\\">Converse overview</a></li>\\n<li><a href=\\"/connect/docs/converse/getting-started\\">Converse Getting Started</a></li>\\n</ul>\\n"}')}}]);